import { describe, expect, it } from "vitest";
import { checkPasswordHash, generatePasswordHash } from "./password";

describe("Password hashing and verification", () => {
  // Hash generated by Python werkzeug.security.generate_password_hash('correcthorsebatterystaple')
  const pythonScryptHash =
    "scrypt:32768:8:1$zIuoDCrwB0GVLpRU$f2e5ac08534365cd5867c5a57712d963f63a6bea71c8adc9cd098acb3eb9e7b8e35e880addbde21ae7c0c5ba04579d5a9ceb2ffec314cd7d6ae9397cb8519d4b";

  // Hash generated by Python werkzeug.security.generate_password_hash('test', method='pbkdf2:sha256')
  const pythonPbkdf2Hash =
    "pbkdf2:sha256:1000000$meHO12uKy5Y1eXYc$00127772c4875be73f885963c0baf6be4c8c011c8be1f186412568a72f0d6d99";

  it("verifies Python Werkzeug scrypt hash correctly", () => {
    expect(checkPasswordHash(pythonScryptHash, "test")).toBe(true);
    expect(checkPasswordHash(pythonScryptHash, "wrongpassword")).toBe(false);
  });

  it("verifies Python Werkzeug pbkdf2:sha256 hash correctly", () => {
    expect(checkPasswordHash(pythonPbkdf2Hash, "test")).toBe(true);
    expect(checkPasswordHash(pythonPbkdf2Hash, "wrongpassword")).toBe(false);
  });

  it("generates a valid scrypt hash that can be verified", () => {
    const password = "mySecurePassword123!";
    const hash = generatePasswordHash(password);

    expect(hash.startsWith("scrypt:32768:8:1$")).toBe(true);
    expect(checkPasswordHash(hash, password)).toBe(true);
    expect(checkPasswordHash(hash, "wrongPassword")).toBe(false);
  });

  it("handles malformed hash strings gracefully", () => {
    expect(checkPasswordHash("", "test")).toBe(false);
    expect(checkPasswordHash("not-a-hash", "test")).toBe(false);
    expect(checkPasswordHash("scrypt$invalid", "test")).toBe(false);
    expect(checkPasswordHash("unknown:1:2:3$salt$hash", "test")).toBe(false);
  });
});
